<template><div class="page"><div class="page-head"><div><span>FMECA / SIMULATION KNOWLEDGE</span><h2>仿真故障知识库</h2><p>条目来自项目 FMECA 资产，统一呈现故障模式、原因、影响与风险等级。</p></div><el-button @click="reset">重置筛选</el-button></div><div class="stats"><el-card shadow="never"><small>知识条目</small><strong>{{ rows.length }}</strong></el-card><el-card shadow="never"><small>高风险模式</small><strong class="danger">{{ highRisk }}</strong></el-card><el-card shadow="never"><small>覆盖部件</small><strong>{{ components }}</strong></el-card></div><el-card shadow="never"><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索故障模式、原因或部件" style="width:280px"/><el-select v-model="level" clearable placeholder="风险等级" style="width:150px"><el-option label="高" value="高"/><el-option label="中" value="中"/><el-option label="低" value="低"/></el-select><el-select v-model="subsystem" clearable placeholder="系统" style="width:150px"><el-option v-for="x in subsystemOptions" :key="x" :label="x" :value="x"/></el-select></div><el-table :data="filtered" stripe v-loading="loading"><el-table-column prop="subsystem" label="系统" width="90"/><el-table-column prop="mode" label="故障模式" width="130"/><el-table-column prop="location" label="部件" width="130"/><el-table-column prop="cause" label="可能原因"/><el-table-column prop="effect" label="系统影响"/><el-table-column prop="detection" label="检测依据"/><el-table-column prop="level" label="风险" width="80"><template #default="s"><el-tag :type="s.row.level==='高'?'danger':s.row.level==='中'?'warning':'info'">{{ s.row.level }}</el-tag></template></el-table-column></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted}from'vue';const rows=ref([]),loading=ref(false),keyword=ref(''),level=ref(''),subsystem=ref('');const fallback=[{component:'液氧泵',fault_name:'气蚀故障',fault_prob:'0.05',fault_reason:'叶轮磨损、轴承失效',degree_harm:'Ⅱ'},{component:'液氧涡轮',fault_name:'转速下降',fault_prob:'0.3',fault_reason:'转子破坏、叶冠脱落',degree_harm:'Ⅰ~Ⅱ'},{component:'煤油管路',fault_name:'堵塞故障',fault_prob:'0.01',fault_reason:'胶质沉积堵塞',degree_harm:'Ⅱ~Ⅲ'},{component:'煤油主阀',fault_name:'卡滞故障',fault_prob:'0.02',fault_reason:'腐蚀锈蚀异物堵塞',degree_harm:'Ⅱ~Ⅲ'},{component:'燃气发生器',fault_name:'燃气泄漏',fault_prob:'0.1',fault_reason:'密封失效',degree_harm:'Ⅰ'},{component:'燃烧室',fault_name:'燃烧不稳定',fault_prob:'0.2',fault_reason:'燃料混合不均',degree_harm:'Ⅰ'},{component:'尾喷管',fault_name:'喷管堵塞',fault_prob:'0.03',fault_reason:'积碳堵塞',degree_harm:'Ⅰ'},{component:'TVC',fault_name:'效率下降',fault_prob:'0.05',fault_reason:'异物入侵、润滑不足',degree_harm:'Ⅱ'},{component:'RCS',fault_name:'力矩下降',fault_prob:'0.05',fault_reason:'电磁阀线圈烧毁',degree_harm:'Ⅱ'},{component:'栅格舵',fault_name:'舵面卡滞',fault_prob:'0.04',fault_reason:'机械磨损',degree_harm:'Ⅱ'},{component:'控制器',fault_name:'控制器无信号',fault_prob:'0.1',fault_reason:'电源断开、通信故障',degree_harm:'Ⅰ'},{component:'传感器',fault_name:'信号恒偏差',fault_prob:'0.03',fault_reason:'电磁干扰、材料老化',degree_harm:'Ⅲ'},{component:'传感器',fault_name:'卡死故障',fault_prob:'0.03',fault_reason:'电磁干扰、材料老化',degree_harm:'Ⅲ'}];const normalize=x=>({...x,subsystem:['液氧泵','液氧涡轮','煤油管路','煤油主阀','燃气发生器','燃烧室','尾喷管'].includes(x.component)?'推进系统':'控制系统',mode:x.fault_name,location:x.component,cause:x.fault_reason,effect:'对应部件性能下降，影响系统功能',detection:`概率 ${x.fault_prob}，结合遥测趋势与规则检测`,level:String(x.degree_harm).includes('Ⅰ')?'高':String(x.degree_harm).includes('Ⅱ')?'中':'低'});async function load(){loading.value=true;try{const r=await fetch('/api/v1/integrations/algorithm-assets/fmeca/');const d=await r.json();rows.value=(d.results||fallback).map(normalize)}catch{rows.value=fallback.map(normalize)}finally{loading.value=false}}onMounted(load);const filtered=computed(()=>rows.value.filter(x=>(!keyword.value||Object.values(x).join(' ').includes(keyword.value))&&(!level.value||x.level===level.value)&&(!subsystem.value||x.subsystem===subsystem.value)));const highRisk=computed(()=>rows.value.filter(x=>x.level==='高').length),components=computed(()=>new Set(rows.value.map(x=>x.component)).size),subsystemOptions=computed(()=>[...new Set(rows.value.map(x=>x.subsystem))]);function reset(){keyword.value='';level.value='';subsystem.value=''}</script>
<style scoped>.page{max-width:1350px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head span{font-size:12px;color:#1677ff;letter-spacing:1px}.page-head h2{margin:8px 0}.page-head p{margin:0;color:#718198}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:16px}.stats small{color:#718198}.stats strong{display:block;font-size:28px;margin-top:5px}.danger{color:#e34d59}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}@media(max-width:700px){.page-head{display:block}.stats{grid-template-columns:1fr}}</style>
